# ─── Test: CSS Module Proxy Identity ──────────────────────────────────────
class TestCSSModuleProxyIdentity:
    """
    Validate the critical Jest contract: styleMock must return a Proxy
    that returns the key itself for any property access.
    This is what makes `styles.foo` resolve to `"foo"` in tests.
    """

    def test_proxy_identity_behavior(self):
        """The mock must return the property key for any access."""
        if not NODE_AVAILABLE:
            pytest.skip("Node.js not available — proxy test skipped")

        mock_path = MOCK_FILE.resolve().as_posix()
        if os.name == "nt":
            mock_path = mock_path.replace("\\", "\\\\")

        script = (
            f"const mock = require('{mock_path}'); "
            "const results = {"
            "simple: mock.someClass, "
            "nested: mock['nested-class'], "
            "numeric: mock['123'], "
            "empty: mock[''], "
            "unicode: mock['café-☕']"
            "}; "
            "console.log(JSON.stringify(results));"
        )

        result = subprocess.run(
            ["node", "-e", script],
            capture_output=True,
            text=True,
            timeout=30,
            check=True,
        )

        proxy_results = json.loads(result.stdout.strip())
        expected = {
            "simple": "someClass",
            "nested": "nested-class",
            "numeric": "123",
            "empty": "",
            "unicode": "café-☕",
        }

        for key, expected_value in expected.items():
            assert proxy_results[key] == expected_value, (
                f"Proxy identity failed for '{key}': "
                f"expected '{expected_value}', got '{proxy_results[key]}'"
            )

    def test_proxy_handles_symbols(self):
        """Proxy must not break on Symbol property access (e.g., Symbol.iterator)."""
        if not NODE_AVAILABLE:
            pytest.skip("Node.js not available — symbol test skipped")

        mock_path = MOCK_FILE.resolve().as_posix()
        if os.name == "nt":
            mock_path = mock_path.replace("\\", "\\\\")

        script = (
            f"const mock = require('{mock_path}'); "
            "const s = Symbol('test'); "
            "const result = mock[s]; "
            "console.log(JSON.stringify({isString: typeof result === 'string', value: result}));"
        )

        result = subprocess.run(
            ["node", "-e", script],
            capture_output=True,
            text=True,
            timeout=30,
            check=True,
        )

        symbol_result = json.loads(result.stdout.strip())
        # Proxy get trap returns the property key (the symbol) — but JSON can't serialize symbols.
        # The key contract: accessing a symbol property returns the symbol itself.
        assert symbol_result["isString"] is False, (
            "Symbol access should return the symbol, not a string"
        )


