# ─── Test: Idempotency ────────────────────────────────────────────────────
class TestIdempotency:
    """The mock must be safe to require multiple times."""

    def test_multiple_requires_consistent(self):
        """Requiring the mock 5 times must yield identical results."""
        if not NODE_AVAILABLE:
            pytest.skip("Node.js not available — idempotency test skipped")

        mock_path = MOCK_FILE.resolve().as_posix()
        if os.name == "nt":
            mock_path = mock_path.replace("\\", "\\\\")

        script = (
            f"const results = []; "
            f"for (let i = 0; i < 5; i++) {{ "
            f"  const mock = require('{mock_path}'); "
            f"  results.push(JSON.stringify(mock)); "
            f"}} "
            f"console.log(JSON.stringify(results));"
        )

        result = subprocess.run(
            ["node", "-e", script],
            capture_output=True,
            text=True,
            timeout=30,
            check=True,
        )

        outputs = json.loads(result.stdout.strip())
        assert len(outputs) == 5, f"Expected 5 outputs, got {len(outputs)}"
        assert len(set(outputs)) == 1, (
            f"Mock is not idempotent — outputs differ: {outputs}"
        )


